import { useCallback, useState } from 'react';
import {
  JxBadge,
  JxDivider,
  JxSelect,
  JxSlider,
  JxSwitch,
  JxToggle,
} from '@jinx-ui/react';

export type AppearanceTheme = 'light' | 'dark' | 'system';

export interface AppearanceSettings {
  theme: AppearanceTheme;
  scale: number;
  dense: boolean;
  fontFamily: string;
}

export interface AppearanceSettingsScreenProps {
  defaultValue?: Partial<AppearanceSettings>;
  onChange?: (settings: AppearanceSettings) => void;
}

const THEME_ITEMS = [
  { value: 'light', label: 'Светлая' },
  { value: 'dark', label: 'Тёмная' },
  { value: 'system', label: 'Системная' },
];

const THEME_LABELS: Record<AppearanceTheme, string> = {
  light: 'Светлая',
  dark: 'Тёмная',
  system: 'Системная',
};

const FONT_OPTIONS = [
  { value: 'sans', label: 'Inter Tight', meta: 'по умолчанию' },
  { value: 'display', label: 'Fraunces', meta: 'акцидентный' },
  { value: 'mono', label: 'JetBrains Mono', meta: 'моноширинный' },
];

function AppearanceSettingsScreen({
  defaultValue,
  onChange,
}: AppearanceSettingsScreenProps) {
  const [settings, setSettings] = useState<AppearanceSettings>({
    theme: defaultValue?.theme ?? 'system',
    scale: defaultValue?.scale ?? 100,
    dense: defaultValue?.dense ?? false,
    fontFamily: defaultValue?.fontFamily ?? 'sans',
  });

  const update = useCallback(
    (patch: Partial<AppearanceSettings>) => {
      setSettings((prev) => {
        const next = { ...prev, ...patch };
        onChange?.(next);
        return next;
      });
    },
    [onChange],
  );

  return (
    <section
      style={{
        display: 'flex',
        flexDirection: 'column',
        gap: 24,
        maxWidth: 520,
        padding: 24,
        background: 'var(--jx-surface)',
        border: '1px solid var(--jx-border)',
        borderRadius: 'var(--jx-r-lg)',
        boxShadow: 'var(--jx-shadow-sm)',
        color: 'var(--jx-text)',
        fontFamily: 'var(--jx-font-sans)',
      }}
    >
      <header
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          gap: 16,
          flexWrap: 'wrap',
        }}
      >
        <div style={{ display: 'flex', flexDirection: 'column', gap: 4 }}>
          <h2
            style={{
              margin: 0,
              fontFamily: 'var(--jx-font-display)',
              fontSize: 22,
              lineHeight: 1.2,
              color: 'var(--jx-text)',
            }}
          >
            Внешний вид
          </h2>
          <p style={{ margin: 0, fontSize: 14, color: 'var(--jx-text-2)' }}>
            Настройки применяются сразу ко всему интерфейсу.
          </p>
        </div>
        <JxBadge tone="accent" dot>
          {THEME_LABELS[settings.theme]}
        </JxBadge>
      </header>

      <div style={{ display: 'flex', flexDirection: 'column', gap: 8 }}>
        <span style={{ fontSize: 14, color: 'var(--jx-text-2)' }}>Тема</span>
        <JxToggle
          items={THEME_ITEMS}
          value={settings.theme}
          onValueChange={(value) => update({ theme: value as AppearanceTheme })}
        />
      </div>

      <JxSlider
        label="Масштаб интерфейса"
        min={80}
        max={140}
        step={5}
        unit="%"
        showOutput
        value={settings.scale}
        onValueChange={(value) => update({ scale: value })}
      />

      <JxSwitch
        label="Плотная вёрстка"
        checked={settings.dense}
        onChange={(event) => update({ dense: event.target.checked })}
      />

      <JxDivider label="Ещё" />

      <JxSelect
        label="Шрифт"
        placeholder="Выберите шрифт"
        options={FONT_OPTIONS}
        value={settings.fontFamily}
        onValueChange={(value) => update({ fontFamily: value })}
      />
    </section>
  );
}

export default AppearanceSettingsScreen;

